export function VisualCountriesListing() {
  const [query, setQuery] = useState('');
  const [region, setRegion] = useState('all');
  const [filters, setFilters] = useState<string[]>([]);
  const toggleFilter = (filter: string) => setFilters((current) => current.includes(filter) ? current.filter((item) => item !== filter) : [...current, filter]);
  const matches = countryRecords.filter((country) => (region === 'all' || country.region === region) && (!query || country.name.toLowerCase().includes(query.toLowerCase())) && filters.every((filter) => country.tags.includes(filter)));
  const regions = ['all', 'Europe', 'North America', 'Asia', 'Australia & New Zealand', 'Middle East'];
  const quickFilters: [string, string][] = [['budget', 'Budget friendly'], ['ielts', 'IELTS optional'], ['jan', 'January intake'], ['visa', 'High visa success'], ['pr', 'PR friendly'], ['rank', 'Top ranked universities']];
  return <main className="visual-countries-page"><Header active="countries" /><section className="hero"><div className="wrap center"><span className="hero-badge"><Icon name="globe" size={15} /><b>25+</b> destinations · <b>12,000+</b> universities</span><h1>Where will your degree <em>take you?</em></h1><p className="hero-sub">Don't just browse countries — compare what actually decides your choice, side by side.</p><div className="compare-chips">{['Tuition fees', 'Living cost', 'Scholarships', 'Post-study work', 'PR pathways', 'English requirements', 'Intakes'].map((item) => <span key={item}><Icon name="check" size={14} />{item}</span>)}</div><div className="searchbar"><Icon name="search" size={20} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search a country (Canada, UK, Australia...)" aria-label="Search a country" /><button type="button" className="btn btn-p">Search</button></div><div className="qf">{quickFilters.map(([filter, label]) => <button type="button" className={filters.includes(filter) ? 'on' : ''} onClick={() => toggleFilter(filter)} key={filter}><Icon name="check" size={16} />{label}</button>)}</div><div className="stats">{[['25+', 'Destinations'], ['12,000+', 'Universities'], ['300,000+', 'Courses'], ['100+', 'Scholarships'], ['95%', 'Visa success'], ['50,000+', 'Students guided']].map(([number, label]) => <div className="stat" key={label}><b>{number}</b><span>{label}</span></div>)}</div></div></section><section className="region-sec" id="regions"><div className="wrap"><div className="eyebrow">Browse by region</div><h2 className="sec-h" style={{ marginTop: 12 }}>Start with the part of the world you're drawn to.</h2><p className="sec-p">Every destination shown with the numbers students actually decide on — tuition, post-study work rights, and intakes.</p><div className="tabbar"><div className="tabs">{regions.map((item) => <button type="button" className={`tab${region === item ? ' on' : ''}`} onClick={() => setRegion(item)} key={item}>{item === 'all' ? 'All destinations' : item} <span className="n">{item === 'all' ? countryRecords.length : countryRecords.filter((country) => country.region === item).length}</span></button>)}</div></div><div className="res-count">Showing {matches.length} destination{matches.length === 1 ? '' : 's'}</div><div className="cards">{matches.map((country) => <article className="card" key={country.name}>{country.pr ? <span className="pr-badge"><Icon name="globe" size={12} />PR friendly</span> : null}<div className="card-head"><div className="flag">{country.flag}</div><div><h3>{country.name}</h3><div className="sub">{country.universities}</div></div></div><p className="desc">{country.description}</p><div className="facts"><div className="fact"><span><Icon name="star" size={12} />Tuition</span><b>{country.tuition}</b></div><div className="fact"><span><Icon name="briefcase" size={12} />Post-study work</span><b>{country.work}</b></div><div className="fact"><span><Icon name="calendar" size={12} />Popular intake</span><b>{country.intake}</b></div></div><a href={`/countries/${country.name.toLowerCase().replace(/[^a-z]+/g, '-')}`} className="card-cta">Explore {country.name}<Icon name="arrow" size={17} /></a></article>)}</div></div></section><div className="wrap"><section className="cta-band"><div><h2>Confused about choosing the right country?</h2><p>Talk with our expert counsellors and get a clear, personalised plan — at no cost.</p><ul className="cta-list">{['Free profile evaluation', 'University shortlisting', 'Scholarship guidance', 'Visa assistance'].map((item) => <li key={item}><Icon name="check" size={18} />{item}</li>)}</ul><div className="cta-btns"><a href="/counselling" className="btn btn-w btn-lg">Get free counselling</a><a href="/signup" className="btn btn-o btn-lg">Create free account</a></div></div><div className="cta-art" aria-hidden="true"><Icon name="globe" size={200} /></div></section></div><section className="az-sec" id="az"><div className="wrap"><div className="eyebrow">Every destination</div><h2 className="sec-h" style={{ marginTop: 12 }}>Browse every destination A–Z</h2><p className="sec-p">Jump straight to a country and see what's on offer at each level.</p><div className="alpha">{'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').map((letter) => <a href={`#az-${letter}`} key={letter}>{letter}</a>)}</div><div className="az-grid">{countryRecords.map((country) => <a className="az-tile" id={`az-${country.name[0]}`} href={`/countries/${country.name.toLowerCase().replace(/[^a-z]+/g, '-')}`} key={country.name}><span className="t"><span className="fl">{country.flag}</span><h3>{country.name}</h3></span><p>{country.description}</p><div className="progs">{country.programs.map((program) => <span key={program}>{program}</span>)}</div><span className="go">Study in {country.name}<Icon name="arrow" size={16} /></span></a>)}</div></div></section><div className="wrap"><section className="cta2"><h2>Ready to start your study abroad journey?</h2><p>Create your free account to save universities, compare countries, track applications, and connect with counsellors.</p><div className="cta2-btns"><a href="/signup" className="btn btn-p btn-lg">Create free account</a><a href="/counselling" className="btn btn-s btn-lg">Book free consultation</a></div></section></div><section className="cons-sec" id="consultants"><div className="wrap"><div className="eyebrow">Study abroad consultants</div><h2 className="sec-h" style={{ marginTop: 12 }}>Guidance from people who know your destination.</h2><p className="sec-p">Get personalised guidance from experienced education consultants who specialise in your preferred study destination.</p><div className="cons-grid">{countryRecords.slice(0, 9).map((country) => <article className="cons" key={country.name}><div className="cons-top"><span className="fl">{country.flag}</span><h3>Study in {country.name} Consultants</h3></div><span className="free-badge">Free consultation</span><p>{country.description}</p><a className="view" href="/counselling">View consultants <Icon name="arrow" size={16} /></a></article>)}</div></div></section><section className="final"><div className="wrap"><div className="eyebrow">Personalised shortlist</div><h2>Not sure which country fits you?</h2><p>Answer a few simple questions and receive a personalised shortlist of countries, universities, scholarships, and courses based on your academic profile.</p><div className="final-btns"><a href="/counselling" className="btn btn-w btn-lg">Find my best match</a><a href="/counselling" className="btn btn-o btn-lg">Talk to a counsellor</a></div><div className="trust"><div><Icon name="shield" size={16} />No cost, no obligation</div><div><Icon name="clock" size={16} />Response within 24 hours</div><div><Icon name="users" size={16} />50,000+ students guided</div></div></div></section><footer>© 2026 Universta · Tuition, visa and intake figures are indicative — always verify with official university and government sources.</footer></main>;
}

function SubjectKpi({ label, value, icon = 'chart' }: { label: string; value: string; icon?: IconName }) { return <div className="kpi"><div className="kk"><Icon name={icon} size={14} />{label}</div><div className="kv">{value}</div></div>; }
function SubjectBlockHead({ eyebrow, title, subtitle, link }: { eyebrow: string; title: string; subtitle?: string; link?: string }) { return <div className="block-head row-between"><div><span className="eyebrow">{eyebrow}</span><h2>{title}</h2>{subtitle ? <p className="sub">{subtitle}</p> : null}</div>{link ? <a href={link} className="link-more">Explore more <Icon name="arrow" size={16} /></a> : null}</div>; }

export function VisualSubjectDetail({ slug = 'computer-science' }: { slug?: string }) {
  const name = slug === 'computer-science' ? 'Computer Science' : slug.replace(/-/g, ' ');
  const [saved, setSaved] = useState(false);
  const [openFaq, setOpenFaq] = useState<number | null>(null);
  const sectionClass = (white = false) => `block${white ? ' section-card' : ''}`;
  return <main className="visual-subject-page"><Header active="subjects" /><div className="wrap crumbs"><nav aria-label="Breadcrumb"><ol><li><a href="/">Home</a></li><li className="sep">/</li><li><a href="/subjects">Subjects</a></li><li className="sep">/</li><li aria-current="page">{name}</li></ol></nav></div><section className="hero"><div className="wrap"><div className="hero-banner"><span className="hero-parent"><Icon name="cap" size={14} /> Discipline · Computing &amp; IT</span><h1>{name}</h1><p className="lede">The study of computation, algorithms, data and intelligent systems — one of the world's most in-demand and future-proof fields. Explore what it takes, where to study, and where it leads.</p><div className="hero-metrics">{[['12,600', 'Courses worldwide'], ['1,540', 'Universities'], ['25+', 'Countries'], ['1–4 yrs', 'Avg. duration'], ['$28k/yr', 'Avg. tuition'], ['$96k', 'Avg. grad salary']].map(([value, label]) => <div className="hm" key={label}><div className="v">{value}</div><div className="k">{label}</div></div>)}</div><div className="hero-cta"><a href="/courses" className="btn btn-white">Explore Courses</a><a href="#universities" className="btn btn-glass">Find Universities</a><a href="/counselling" className="btn btn-glass"><Icon name="users" /> Book Free Counselling</a></div><div className="hero-actions"><button type="button" className={saved ? 'on' : ''} onClick={() => setSaved(!saved)}><Icon name="heart" size={15} /> {saved ? 'Saved subject' : 'Save subject'}</button><button type="button"><Icon name="book" size={15} /> Compare</button><button type="button"><Icon name="arrow" size={15} /> Share</button></div></div></div></section><nav className="toc" aria-label="On this page"><div className="wrap toc-inner">{['glance', 'about', 'why', 'skills', 'specializations', 'careers', 'countries', 'universities', 'scholarships', 'cost', 'match', 'faq'].map((item, index) => <a href={`#${item}`} className={index === 0 ? 'active' : ''} key={item}>{item === 'glance' ? 'At a glance' : item}</a>)}</div></nav><div className="wrap layout"><div className="main"><section className={sectionClass()} id="glance" style={{ paddingTop: 28 }}><SubjectBlockHead eyebrow="Snapshot" title={`${name} at a glance`} /><div className="kpi-grid">{[['Courses worldwide', '12,600', 'book'], ['Universities', '1,540', 'building'], ['Countries', '25+', 'globe'], ['Avg. duration', '1–4 yrs', 'clock'], ['Avg. tuition', '$28k/yr', 'star']].map(([label, value, icon]) => <SubjectKpi key={label} label={label} value={value} icon={icon as IconName} />)}</div></section><section className={sectionClass()} id="about"><SubjectBlockHead eyebrow="Overview" title={`About ${name}`} /><div className="prose"><h3>What is Computer Science?</h3><p>Computer Science is the study of computation — how problems are solved with algorithms, how data is structured and processed, and how software and intelligent systems are designed and built. It spans theory and practice.</p><h3>Why study this subject?</h3><p>It is among the most in-demand and highest-paid fields globally, with roles across every industry and strong post-study work pathways in top destinations.</p><h3>History, global importance &amp; future scope</h3><p>From its mathematical roots to today's AI revolution, Computer Science now underpins healthcare, finance, transport, entertainment and government.</p></div><div className="ai-summary"><div className="ai-tag"><Icon name="chart" size={16} /> AI subject summary</div><div className="ai-rows">{[['Best for', 'Problem solvers who enjoy technology'], ['Work style', 'Project-based, collaborative and global'], ['Growth', 'High demand across major industries'], ['Study mode', 'Campus, online and hybrid pathways']].map(([label, value]) => <div className="ai-row" key={label}><span>{label}</span><b>{value}</b></div>)}</div></div></section><section className={sectionClass(true)} id="why"><SubjectBlockHead eyebrow="Make the case" title={`Why study ${name}?`} /><div className="grid g4">{[['High demand', 'Technology roles continue to grow globally.', 'chart'], ['Strong salaries', 'Transferable skills support long-term careers.', 'star'], ['Global mobility', 'Study and work across leading destinations.', 'globe'], ['Future-proof', 'Build a foundation for emerging fields.', 'shield']].map(([title, description, icon]) => <div className="card why-card" key={title}><div className="why-ic"><Icon name={icon as IconName} /></div><h3>{title}</h3><p>{description}</p></div>)}</div></section><section className={sectionClass()} id="skills"><SubjectBlockHead eyebrow="Capabilities" title="Skills you'll learn" /><div className="grid g2">{[['Technical skills', ['Programming', 'Algorithms', 'Data structures', 'Systems design']], ['Professional skills', ['Problem solving', 'Communication', 'Research', 'Project management']]].map(([title, skills]) => <div className="card skill-group" key={String(title)}><h3><span className="si"><Icon name="code" /></span>{title}</h3><div className="skill-tags">{(skills as string[]).map((skill) => <span key={skill}>{skill}</span>)}</div></div>)}</div></section><section className={sectionClass(true)} id="curriculum"><SubjectBlockHead eyebrow="What you'll study" title="Subjects you'll study" /><div className="curr-grid">{['Programming fundamentals', 'Data structures & algorithms', 'Operating systems', 'Databases', 'Artificial intelligence', 'Computer networks', 'Software engineering', 'Human-computer interaction'].map((item) => <div className="curr-item" key={item}><span className="curr-ic"><Icon name="book" /></span><span><h4>{item}</h4><p>Core study pathway</p></span></div>)}</div></section><section className={sectionClass()} id="specializations"><SubjectBlockHead eyebrow="Focus areas" title="Specializations" link={`/subjects/${slug}/specializations`} /><div className="grid g2">{specializationRecords.slice(0, 6).map((record) => <a href={`/subjects/${slug}/specializations`} className="card spec-card" key={record.name}><span className="spec-ic"><Icon name={record.icon} /></span><span><span className="sn">{record.name}</span><span className="sd">{record.description}</span></span><span className="go"><Icon name="arrow" size={16} /></span></a>)}</div></section><section className={sectionClass(true)} id="careers"><SubjectBlockHead eyebrow="Where it leads" title="Career opportunities" /><div className="grid g3">{['Software Engineer', 'Data Scientist', 'AI / ML Engineer'].map((career) => <div className="card career-card" key={career}><div className="career-top"><div className="career-ic"><Icon name="briefcase" /></div><div><h3>{career}</h3><div className="cind">Technology &amp; digital industries</div></div></div><div className="career-rows"><div className="career-row"><span>Avg. salary</span><span>$96k</span></div><div className="career-row"><span>Future demand</span><span>Very high</span></div></div><a href="/courses" className="go">Explore pathways <Icon name="arrow" size={14} /></a></div>)}</div></section><section className={sectionClass()} id="industries"><SubjectBlockHead eyebrow="Who hires" title="Top industries hiring" /><div className="grid g4">{['Technology', 'Finance', 'Healthcare', 'Government', 'E-commerce', 'Media', 'Transport', 'Education'].map((industry) => <div className="card mini-card" key={industry}><span className="mini-ic"><Icon name="building" /></span><span><h3>{industry}</h3><span className="mc-sub">Technology pathways</span></span></div>)}</div></section><section className={sectionClass(true)} id="countries"><SubjectBlockHead eyebrow="Where to study" title={`Best countries to study ${name}`} /><div className="grid g3">{['United States', 'Canada', 'United Kingdom'].map((country) => <a href="/countries" className="card country-card" key={country}><div className="country-top"><span className="cc-tile">{country.slice(0, 2).toUpperCase()}</span><span><h3>{country}</h3><span className="cwork">Strong post-study work</span></span></div><div className="country-rows"><span className="cr"><span className="k">Programs</span><span className="v">4,800</span></span><span className="cr"><span className="k">Tuition</span><span className="v">$28k/yr</span></span></div><span className="go">Explore country <Icon name="arrow" size={14} /></span></a>)}</div></section><section className={sectionClass()} id="universities"><SubjectBlockHead eyebrow="Best for the field" title="Top universities" link="/universities" /><div className="grid g2">{[['MIT', 'Massachusetts Institute of Technology', 'QS #1'], ['CMU', 'Carnegie Mellon University', 'QS #4'], ['OX', 'University of Oxford', 'QS #3'], ['UT', 'University of Toronto', 'QS #12']].map(([mark, university, rank]) => <a href="/universities" className="card uni-card" key={university}><span className="uni-logo">{mark}</span><span><h3>{university}</h3><span className="um">18 programs · Computer Science</span></span><span className="rank">{rank}</span></a>)}</div></section><section className={sectionClass(true)} id="courses"><SubjectBlockHead eyebrow="Programs" title="Popular courses" link="/courses" /><div className="grid g3">{courseFixture.slice(0, 3).map((course) => <a href="/courses" className="card course-card" key={course[0]}><span className="cc-lvl">{course[4]}</span><h3>{course[0]}</h3><div className="cc-uni">{course[1]}</div><div className="cc-facts"><div><b>{course[5]}</b>Duration</div><div><b>{course[6]}</b>Tuition</div></div></a>)}</div></section><section className={sectionClass()} id="scholarships"><SubjectBlockHead eyebrow="Funding" title="Scholarships" link="/scholarships" /><div className="grid g3">{[['STEM', 'Global AI Excellence Award', '$20,000'], ['Merit', 'Women in Tech Scholarship', '$15,000'], ['Government', 'Cyber Security Research Award', '$10,000']].map(([category, title, amount]) => <div className="card schol" key={title}><span className="s-cat">{category}</span><h3>{title}</h3><span className="s-amt">{amount}</span><span className="s-meta"><span>Eligibility: subject applicants</span><span>Deadline: 30 Nov 2026</span></span></div>)}</div></section><section className={sectionClass(true)} id="admissions"><SubjectBlockHead eyebrow="Apply" title="Admission requirements" /><div className="adm-grid">{[['Academic background', ['Relevant degree or equivalent', 'Strong academic record']], ['Application materials', ['Statement of purpose', 'References and transcripts']]].map(([title, items]) => <div className="card adm" key={String(title)}><h3><span className="ai"><Icon name="check" /></span>{title}</h3><ul>{(items as string[]).map((item) => <li key={item}><Icon name="check" size={16} />{item}</li>)}</ul></div>)}</div></section><section className={sectionClass()} id="cost"><SubjectBlockHead eyebrow="Investment" title="Cost to study" /><div className="cost-wrap"><div className="cost-list">{[['Tuition', '100%'], ['Living costs', '65%'], ['Visa & insurance', '28%'], ['Books and materials', '18%']].map(([label, width]) => <div className="cost-row" key={label}><span className="cn"><Icon name="star" size={16} />{label}</span><span className="cost-bar"><span className="cf" style={{ width }} /></span><span className="cv">$28k/yr</span></div>)}</div><div className="cost-total"><span className="ct-l">Indicative annual total</span><span className="ct-v">$42k</span><span className="ct-s">Tuition + living costs</span></div></div></section><section className={sectionClass(true)} id="dashboard"><SubjectBlockHead eyebrow="Outlook" title="Career outlook dashboard" /><div className="dash-grid">{[['Employment rate', '92%', '92%'], ['Demand growth', '+30%', '80%'], ['Global mobility', 'High', '74%']].map(([label, value, width]) => <div className="card dash-card" key={label}><div className="dk">{label}</div><div className="dash-num">{value}</div><div className="dash-bar"><span className="df" style={{ width }} /></div><div className="dnote">Published pathway indicator</div></div>)}</div></section><section className={sectionClass()} id="future"><SubjectBlockHead eyebrow="Looking ahead" title="Future scope" /><div className="prose"><p>New opportunities continue to emerge across AI, cloud computing, data, cybersecurity, research and software engineering. Explore a specialization and verify program details with official sources.</p></div></section><section className={sectionClass(true)} id="stories"><SubjectBlockHead eyebrow="Real journeys" title="Student success stories" /><div className="grid g3">{['RK', 'TS', 'MN'].map((initials, index) => <article className="card story-card" key={initials}><div className="story-top"><span className="story-av">{initials}</span><span><b className="story-name">{['Riya K.', 'Tom S.', 'Maya N.'][index]}</b><span className="story-meta">Computer Science pathway</span></span></div><div className="story-stars"><Icon name="star" size={15} /><Icon name="star" size={15} /><Icon name="star" size={15} /><Icon name="star" size={15} /><Icon name="star" size={15} /></div><p>“The structured pathway helped me compare my next steps clearly.”</p></article>)}</div></section><section className={sectionClass()} id="match"><SubjectBlockHead eyebrow="Find your fit" title={`Is ${name} right for you?`} /><div className="match-out"><div className="match-copy"><p>Computer Science is a strong fit if you enjoy problem solving, systems thinking, and building practical solutions.</p><a href="/counselling" className="btn btn-primary">Get guidance</a></div><div className="match-form"><div className="card mini-card"><span className="mini-ic"><Icon name="code" /></span><span><h3>Enjoy solving problems?</h3><span className="mc-sub">Explore the pathway</span></span></div><div className="card mini-card"><span className="mini-ic"><Icon name="users" /></span><span><h3>Want global options?</h3><span className="mc-sub">Compare destinations</span></span></div></div></div></section><section className={sectionClass(true)} id="related"><SubjectBlockHead eyebrow="Keep exploring" title="Related subjects" /><div className="grid g3">{['Data Science', 'Information Technology', 'Artificial Intelligence'].map((item) => <VisualCard key={item} title={item} subtitle="Explore subject pathway" icon="code" href="/subjects" />)}</div></section><section className={sectionClass()} id="resources"><SubjectBlockHead eyebrow="Learn" title="Resources & guides" /><div className="explore-grid">{['Career guide', 'Course finder', 'Scholarship guide', 'Visa checklist', 'Blog', 'Cost calculator'].map((item) => <a href="/courses" className="card explore-item" key={item}><span className="explore-ic"><Icon name="book" /></span><span className="en">{item}</span><span className="go"><Icon name="arrow" size={16} /></span></a>)}</div></section><section className={sectionClass(true)} id="consultants"><SubjectBlockHead eyebrow="Guidance" title="Find a study abroad consultant" /><div className="grid g3">{['Asha', 'Daniel', 'Maya'].map((consultant) => <div className="card consult-card" key={consultant}><div className="consult-top"><span className="consult-av">{consultant[0]}</span><span><h3>{consultant} · Computer Science</h3><span className="consult-rate"><Icon name="star" size={13} /> 4.9 · Verified guidance</span></span></div><p className="prose">Talk through your destination and course shortlist.</p><a href="/counselling" className="btn btn-outline btn-sm">View guidance</a></div>)}</div></section><section className={sectionClass()} id="faq"><SubjectBlockHead eyebrow="Answers" title="Frequently asked questions" /><div className="faq">{['What is Computer Science?', 'Which countries are best for Computer Science?', 'How much does it cost to study?', 'What careers can I pursue?'].map((question, index) => <div className={`faq-item${openFaq === index ? ' open' : ''}`} key={question}><button type="button" className="faq-q" onClick={() => setOpenFaq(openFaq === index ? null : index)}><span>{question}</span><span className="fic"><Icon name="arrow" size={15} /></span></button>{openFaq === index ? <div className="faq-a" style={{ maxHeight: 200 }}><div className="faq-a-inner">Use published course and subject records as a starting point, then verify the decision with official sources.</div></div> : null}</div>)}</div></section><section className={sectionClass(true)} id="explore"><SubjectBlockHead eyebrow="Keep exploring" title="Explore more" /><div className="explore-grid">{['Specializations', 'Universities', 'Courses', 'Scholarships', 'Countries', 'Consultants'].map((item) => <a href="/courses" className="card explore-item" key={item}><span className="explore-ic"><Icon name="arrow" /></span><span className="en">{item}</span><span className="go"><Icon name="arrow" size={16} /></span></a>)}</div></section></div><aside className="side"><div className="side-card"><span className="eyebrow">At a glance</span><h3>{name}</h3><p>Published subject snapshot</p><a href="/courses" className="btn btn-primary btn-block">Browse courses</a><div className="side-links"><a href="#about">About</a><a href="#specializations">Specializations</a><a href="#careers">Careers</a></div></div></aside></div><section className="section wrap"><div className="final-cta"><h2>Ready to study {name} abroad?</h2><p>Explore published courses and start your next conversation with reliable information.</p><div className="cta-row"><a href="/courses" className="btn btn-secondary">Explore courses</a><a href="/counselling" className="btn btn-outline">Get guidance</a></div></div></section><Footer /></main>;
}

export function VisualCountryDetail({ slug = 'canada' }: { slug?: string }) {
  const country = slug === 'canada' ? 'Canada' : slug.replace(/-/g, ' ').replace(/\b\w/g, (letter) => letter.toUpperCase());
  const [openFaq, setOpenFaq] = useState<number | null>(null);
  const countrySection = (id: string, title: string, content: React.ReactNode, alt = false) => <section className={`sec${alt ? ' alt' : ''}`} id={id}><div className="wrap"><div className="head"><div className="eyebrow">Study in {country}</div><h2 className="sh">{title}</h2></div>{content}</div></section>;
  const whyItems = [['A real route to PR', 'Express Entry awards points for Canadian study and Canadian work experience.', 'Most graduates apply within 3 years', 'shield'], ['Three-year work permit', 'A qualifying programme can earn a Post-Graduation Work Permit of up to three years.', 'PGWP up to 36 months', 'briefcase'], ['Lower total cost', 'Tuition typically runs well below comparable international options.', 'CA$18–35k/yr tuition', 'star'], ['Co-op built into the degree', 'Paid work terms can sit inside the programme itself.', 'Common in engineering & business', 'book'], ['Family can come with you', 'Rules vary by programme level and current policy.', 'Verify with official sources', 'users'], ['Three intakes a year', 'January, May and September starts give students more flexibility.', 'Jan · May · Sep', 'calendar']];
  return <main className="visual-country-detail-page"><Header active="countries" /><nav className="jump" aria-label="Page sections"><div className="wrap jump-in">{['why', 'unis', 'subjects', 'intakes', 'documents', 'cost', 'scholarships', 'visa', 'events', 'cities', 'living', 'careers', 'faq', 'howto', 'consultants'].map((item, index) => <a className={index === 0 ? 'on' : ''} href={`#${item}`} key={item}>{item === 'why' ? `Why ${country}` : item.replace('-', ' ')}</a>)}</div></nav><div className="wrap"><div className="crumbs"><a href="/">Home</a><span>›</span><a href="/countries">Countries</a><span>›</span><span>{country}</span></div></div><section className="hero"><div className="wrap hero-grid"><div><div className="h-flag">🇨🇦</div><h1>Study in {country} in 2026</h1><p className="lede">Canada pairs globally ranked universities with a three-year post-study work permit and one of the clearest routes from graduation to permanent residency anywhere.</p><div className="updated"><Icon name="clock" size={15} />Last verified 18 July 2026 · official and university sources</div><div className="hero-btns"><a href="/counselling" className="btn btn-p btn-lg">Get free counselling</a><a href="/signup" className="btn btn-s btn-lg">Create account &amp; start application</a></div></div><aside className="quickfacts"><h3>{country} at a glance</h3><p className="qf-note">2026 intake · figures are indicative</p>{[['Tuition', 'CA$18–35k/yr', 'star'], ['Living cost', 'CA$12–18k/yr', 'home'], ['Post-study work', 'Up to 3 years', 'briefcase'], ['Intakes', 'Jan · May · Sep', 'calendar'], ['English', 'IELTS 6.0–6.5', 'book'], ['PR pathway', 'Yes — Express Entry', 'shield']].map(([label, value, icon]) => <div className="qf-row" key={label}><span><Icon name={icon as IconName} size={15} />{label}</span><b>{value}</b></div>)}</aside></div></section><div className="wrap"><div className="ad ad-lb"><div className="lab">Advertisement</div><div className="box">Leaderboard · 970×120 desktop / 320×100 mobile</div></div></div>{countrySection('why', `Why study in ${country} in 2026`, <div className="why-grid">{whyItems.map(([title, text, stat, icon]) => <article className="why" key={title}><div className="ic"><Icon name={icon as IconName} /></div><h3>{title}</h3><p>{text}</p><span className="stat">{stat}</span></article>)}</div>, true)}{countrySection('unis', `Partnered universities in ${country}`, <div className="partners">{[['UT', 'University of Toronto', 'Toronto, Ontario'], ['UW', 'University of Waterloo', 'Waterloo, Ontario'], ['SF', 'Simon Fraser University', 'Burnaby, British Columbia'], ['DA', 'Dalhousie University', 'Halifax, Nova Scotia']].map(([mark, name, location]) => <article className="partner" key={name}><span className="p-badge">✓ Direct partner</span><div className="p-logo">{mark}</div><div style={{ flex: 1 }}><h3>{name}</h3><div className="loc">{location}</div><div className="p-meta"><div><span>Tuition</span><b>CA$24–46k</b></div><div><span>Decision</span><b>3–5 weeks</b></div><div><span>Programmes</span><b>300+</b></div></div><div className="p-act"><a href="/courses" className="mini fill">Apply directly</a><a href="/countries/canada" className="mini">View profile</a></div></div></article>)}</div>)}{countrySection('subjects', `Popular subjects in ${country} in 2026`, <div className="subj-grid">{['Computer science & IT', 'Business & management', 'Engineering', 'Health & nursing', 'Data science & analytics', 'Hospitality management', 'Media & communication', 'Supply chain & logistics'].map((item) => <article className="subj" key={item}><div className="ic"><Icon name="book" /></div><h3>{item}</h3><span>Published programmes</span><b>Explore pathways</b></article>)}</div>)}{countrySection('intakes', 'Intakes and deadlines', <div className="intakes">{[['January intake', 'Applications often open from late summer'], ['May intake', 'Flexible start for selected programmes'], ['September intake', 'Largest annual programme selection']].map(([title, text]) => <div className="card intake" key={title}><div className="ic"><Icon name="calendar" /></div><h3>{title}</h3><p>{text}</p><b>Verify each university deadline</b></div>)}</div>, true)}{countrySection('documents', 'Required documents', <div className="docs"><div className="doc-list"><h3>For your application</h3><ul>{['Passport and identity documents', 'Academic transcripts and certificates', 'English-language test score', 'Statement of purpose', 'Letters of recommendation'].map((item) => <li key={item}><Icon name="check" size={16} />{item}</li>)}</ul></div><div className="doc-note"><h3>Source-aware checklist</h3><p>Requirements vary by university, course, applicant profile, and policy. Verify each item before submitting.</p><a href="/counselling" className="btn btn-p">Get document guidance</a></div></div>)}{countrySection('cost', 'Cost to study in Canada', <div className="cost-wrap"><div className="cost-list">{[['Tuition', '$28k/yr', '100%'], ['Living costs', '$15k/yr', '55%'], ['Visa & insurance', '$2k', '20%'], ['Books and materials', '$1k', '12%']].map(([label, value, width]) => <div className="cost-row" key={label}><span className="cn"><Icon name="star" size={16} />{label}</span><span className="cost-bar"><span className="cf" style={{ width }} /></span><span className="cv">{value}</span></div>)}</div><div className="cost-total"><span className="ct-l">Indicative annual total</span><span className="ct-v">CA$42k</span><span className="ct-s">Tuition + living costs</span></div></div>, true)}{countrySection('scholarships', 'Scholarships for international students', <div className="schols">{['Vanier Canada Graduate Scholarships', 'Ontario Graduate Scholarship', 'University-specific entrance awards'].map((item) => <div className="schol" key={item}><span className="s-cat">Funding</span><h3>{item}</h3><div className="s-amt">Source dependent</div><div className="s-meta"><span>Eligibility varies</span><span>Check official deadline</span></div></div>)}</div>)}{countrySection('visa', 'Student visa and work rights', <div className="docs"><div className="doc-list"><h3>Study permit basics</h3><ul>{['Letter of acceptance', 'Proof of funds', 'Biometrics and application', 'Provincial attestation where required'].map((item) => <li key={item}><Icon name="check" size={16} />{item}</li>)}</ul></div><div className="doc-note"><h3>Policy-sensitive information</h3><p>Visa and work rules can change. Confirm current requirements with the official immigration authority.</p><a href="/counselling" className="btn btn-p">Check guidance</a></div></div>, true)}{countrySection('events', 'Upcoming events and webinars', <div className="events">{['Canada admissions webinar', 'Scholarship planning session', 'Visa readiness workshop'].map((item) => <div className="event" key={item}><span className="date">2026</span><h3>{item}</h3><p>Published event information.</p><a href="/counselling" className="more">Reserve a place <Icon name="arrow" size={15} /></a></div>)}</div>)}{countrySection('cities', 'Popular cities for international students', <div className="cities">{['Toronto', 'Vancouver', 'Montreal', 'Calgary'].map((city) => <div className="city" key={city}><span className="city-icon"><Icon name="building" /></span><h3>{city}</h3><p>Universities, work options, and student life.</p></div>)}</div>, true)}{countrySection('living', 'Living costs and student life', <div className="prose"><p>Living costs vary by city and lifestyle. Compare accommodation, transport, food, insurance, and daily expenses before choosing a destination.</p></div>)}{countrySection('careers', 'Career opportunities after graduation', <div className="careers"><div className="career-copy"><h3>Build your next step</h3><p>Use verified course and work information to map your study destination to your goals.</p><a href="/courses" className="btn btn-p">Explore courses</a></div><div className="career-list">{['Software Engineer', 'Business Analyst', 'Data Scientist', 'Nurse'].map((item) => <div className="career-row" key={item}><span>{item}</span><b>Published pathway</b></div>)}</div></div>, true)}{countrySection('faq', 'Frequently asked questions', <div className="faq">{['How much does it cost to study in Canada?', 'Can I work while studying?', 'How long is the post-study work permit?', 'Which intake should I choose?'].map((question, index) => <div className={`faq-item${openFaq === index ? ' open' : ''}`} key={question}><button type="button" className="faq-q" onClick={() => setOpenFaq(openFaq === index ? null : index)}><span>{question}</span><span className="fic"><Icon name="arrow" size={15} /></span></button>{openFaq === index ? <div className="faq-a" style={{ maxHeight: 200 }}><div className="faq-a-inner">Verify current guidance with official university and government sources.</div></div> : null}</div>)}</div>)}{countrySection('howto', 'How to study in Canada', <div className="howto">{['Choose your course', 'Check entry requirements', 'Prepare your application', 'Apply and plan your visa'].map((item, index) => <div className="how" key={item}><span className="num">{index + 1}</span><h3>{item}</h3><p>Follow the published next step.</p></div>)}</div>, true)}{countrySection('blogs', 'Resources and guides', <div className="blogs">{['Canada study guide', 'Cost planning checklist', 'Visa readiness guide'].map((item) => <div className="blog" key={item}><span className="blog-type">Guide</span><h3>{item}</h3><p>Source-aware information for your shortlist.</p><a href="/counselling" className="more">Read guide <Icon name="arrow" size={15} /></a></div>)}</div>)}{countrySection('consultants', 'Find a study abroad consultant', <div className="cons-grid">{['Asha', 'Daniel', 'Maya', 'Rohan', 'Sara', 'Noah'].map((person) => <article className="cons" key={person}><div className="cons-top"><span className="fl">{person[0]}</span><h3>{person} · {country}</h3></div><span className="c-badge">Free consultation</span><p>Talk through your country and course shortlist with a verified guidance option.</p><a href="/counselling" className="c-btn">View consultant <Icon name="arrow" size={15} /></a></article>)}</div>, true)}<section className="sec final"><div className="wrap"><div className="eyebrow">Personalised shortlist</div><h2>Ready to study in {country}?</h2><p>Get a clear shortlist of courses, universities and next steps.</p><div className="final-btns"><a href="/counselling" className="btn btn-w">Find my best match</a><a href="/counselling" className="btn btn-o">Talk to a counsellor</a></div></div></section><Footer /></main>;
}
